from common6 import *
import pandas as pd,re
def table(rows):
 if not rows:return '_No rows._'
 d=pd.DataFrame(rows)
 def fmt(v):
  if isinstance(v,(dict,list)):return json.dumps(clean(v),ensure_ascii=False).replace('|','\\|')
  if isinstance(v,float):return '' if not np.isfinite(v) else f'{v:.8g}'
  return str(v).replace('|','\\|')
 return '| '+' | '.join(map(str,d.columns))+' |\n|'+'|'.join(['---']*len(d.columns))+'|\n'+'\n'.join('| '+' | '.join(fmt(v) for v in row)+' |' for row in d.itertuples(index=False,name=None))
def figures(i,t):
 os.environ['MPLCONFIGDIR']=str(PRIVATE/'matplotlib_cache');import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 names=['I4_ATTENTION_HEATMAP']
 def bars(rows,group,title,name,metric='PR_AUC'):
  d=pd.DataFrame(rows);d.to_csv(OUT/f'{name}_data.csv',index=False)
  labels=[];mean=[];sd=[]
  for key,a in d.groupby(group,sort=False):
   labels.append(' · '.join(map(str,key)) if isinstance(key,tuple) else str(key));mean.append(a[metric].mean());sd.append(a[metric].std(ddof=1) if len(a)>1 else 0)
  fig,ax=plt.subplots(figsize=(max(7,len(labels)*.8),5));ax.bar(range(len(labels)),mean,yerr=sd,capsize=3,color='#287f8e');ax.set_xticks(range(len(labels)),labels,rotation=30,ha='right');ax.set(ylabel=metric+' (mean ± seed SD)',title=title);ax.grid(axis='y',alpha=.2);fig.tight_layout();fig.savefig(OUT/f'{name}.png',dpi=300);plt.close(fig);names.append(name)
 bars([r for r in i['order_history'] if r['model']=='TRACE'],['condition'],'TRACE order and history · development VALIDATION','I1_TRACE_ORDER_HISTORY')
 bars(i['same_information'],['model'],'Identical 20 × 13 inputs · development VALIDATION','I2_SAME_INFORMATION')
 bars(i['multi_day'],['model'],'Multi-day cohort G · development users only','I3_MULTI_DAY')
 vr=t['validation'];bars([r for r in vr if r['part']=='T1' or (r['part']=='reference' and r['reference'].startswith('matched'))],['config','model'],'Window-length sensitivity · development VALIDATION','T1_WINDOW_LENGTH')
 bars([r for r in vr if r['part']=='T2' or (r['part']=='reference' and r['reference'].startswith('matched'))],['config','model'],'Feature-set sensitivity · development VALIDATION','T2_FEATURE_SETS')
 bars(t['r42_test'],['model'],'New r4.2 TRAIN models · single TEST evaluation','T3_R42_TEST')
 d=pd.DataFrame(i['attention_CIs']);d.to_csv(OUT/'I4_ATTENTION_EFFECT_CIS_data.csv',index=False);fig,axes=plt.subplots(1,2,figsize=(10,4.8))
 for ax,kind in zip(axes,['delete','retain']):
  for seed in SEEDS:
   a=d[(d.seed==seed)&(d.intervention==kind)].sort_values('k');ax.errorbar(a.k,a.estimate,yerr=np.maximum(0,np.array([a.estimate-a.ci95_low,a.ci95_high-a.estimate])),marker='o',capsize=3,label=f'Seed {seed}')
  ax.axhline(0,color='0.5',lw=1);ax.set(xlabel='Number of timesteps k',ylabel='Top − matched random confidence gap',title='Deletion' if kind=='delete' else 'Retention / sufficiency gap');ax.grid(alpha=.2);ax.legend()
 fig.tight_layout();fig.savefig(OUT/'I4_ATTENTION_EFFECT_CIS.png',dpi=300);plt.close(fig);names.append('I4_ATTENTION_EFFECT_CIS');return names
def main():
 i=read(OUT/'I_RESULTS.json');t=read(OUT/'T_RESULTS.json');runs=read(OUT/'TRAINING_RESULTS_PHASE6.json');ip=read(OUT/'INFERENCE_PROTOCOL_FROZEN.json');data=read(OUT/'DATA_MANIFEST_PHASE6.json');amend=read(OUT/'AMENDMENT4_RECEIPT.json');tp=read(OUT/'TRAINING_PROTOCOL_FROZEN.json')
 names=figures(i,t);skips=[dict(config=r['phase6_config'],model=r['model'],seed=r['seed'],status=r['status'],reason=r.get('reason','')) for r in runs if r['status']!='ok']
 deviations=[
  'Phase 5B was superseded and not run separately.',
  'Strict HOLDOUT exclusion restricts every r5.2 Phase6 analysis to 1500 development users and 48000 original 20-day VALIDATION windows (473 positives). Historical all-user TRACE mean AP 0.942842 is context only. Existing frozen all-user checkpoints/scalers/TRAIN medians are reused as requested, so historical training included the later HOLDOUT users; Phase6 never reads their activity or scores for analysis and never fits on them.',
  'The full historical multi-day cohort has 613 positives, 26 users/answer-file incidents and 63272 negatives. Its allowed development-only subset has 384 positives from 16 users/answer-file incidents and 47527 negatives. The full cohort was not evaluated because it contains excluded HOLDOUT users.',
  'The manuscript 484-window/151-user explanation cohort belongs to r4.2, as previously established in Phase3. I4 follows the existing actual r5.2 deterministic 25th/50th/75th percentile TP/TN/FP/FN case protocol per seed. The requested heatmap uses seed42 median cases only. Interventions use the existing masked-softmax helper, which zeros excluded timestep vectors and removes them from attention while retaining chronological positions. This is more specific than the manuscript shorthand of zero replacement with attention recomputation.',
  'Attention CIs are exploratory, sequence-weighted user-cluster intervals on the selected deterministic cases. The small, outcome-selected case sample limits population inference. Top-minus-random deletion >0 means larger confidence loss; retention-gap <0 means better sufficiency than random. These are model-relative input interventions, not causal employee-behaviour explanations.',
  'New 10-day and 30-day models have their own completed-window labels and within-period endpoints; validation populations differ. Their AP differences cannot isolate window length from cohort/label prevalence. T1 reports the matched development-only 20-day TRACE alongside the original all-user checkpoint restricted to development validation; T2 gives paired contrasts against both 13-feature references, explicitly disclosing the historical training-membership difference.',
  'Preparation initially hit the old 20-day-only summary shape guard, before any training started. The 40-feature aggregation equations were copied with only the allowed timestep length generalized, and exact T20 equality was verified on synthetic inputs. No hyperparameter changed. Inference preparation initially hit a NumPy private-header API mismatch, before inference; it was corrected to the supported public reader. Neither preparation failure evaluated r4.2 TEST or triggered a model retry.',
  'F6_PRIMITIVES and F29 use the existing revision_v0.2 feature definitions. Only selected development-user slices of the existing raw daily F29 caches were materialized. All 13 shared channels exactly matched the filtered authoritative daily table. Daily TRAIN-only median imputation and population standardization were refitted per configuration; no extra missingness indicator columns were added (matching the realized study schema).',
  'All single runs have a 7200-second limit. Only this task’s child process can be stopped on timeout. GPU allocator usage is capped at 35%, CPU numerical libraries and tree models use two threads, neural forward passes pause cooperatively, and no other chat, window, process or repository is managed.',
  'Checkpoint selection maximizes VALIDATION AP; thresholds maximize VALIDATION F1 using the frozen Phase2 candidate rule. All validation results are selection-set results, not independent test claims. r4.2 TEST is the sole newly evaluated TEST partition; the old r5.2 TEST partition remained sealed.'
 ]
 logrows=[dict(model='TRACE' if r['model']=='TA2' else 'Attention-linear prerequisite' if r['model']=='AL_PRECURSOR' else r['model'],config=r['phase6_config'],seed=r['seed'],status=r['status'],epochs=r.get('epochs'),best_epoch=r.get('best_epoch'),validation_AP=r.get('dev_validation_pr_auc'),duration_seconds=r.get('wall_seconds'),threshold=r.get('threshold')) for r in runs]
 result=dict(phase='6',exploratory=True,completed_utc=utc(),amendment4=amend,training_protocol=tp,inference_protocol=ip,data_manifest=data,training_log=logrows,full_training_results=runs,part_I=i,part_T=t,figures=[dict(png=n+'.png',csv=n+'_data.csv',dpi=300) for n in names],skips=skips,deviations=deviations,integrity=dict(r52_test_sealed=True,holdout_user_activity_used=False,training_only_TRAIN=True,selection_only_VALIDATION=True,existing_repositories_modified=False,pushed=False))
 dump(OUT/'PHASE6_RESULTS.json',result)
 lines=['# Phase 6: final-model re-runs (exploratory)','',f'Completed UTC: {utc()}','',f'Training: {sum(r["status"]=="ok" for r in runs)}/{len(runs)} runs succeeded. All outcomes, including any failures, dependency skips or timeouts, are retained. TRACE means TA2/F11, with task + 0.5 teacher-logit MSE + 0.5 route KL. No tuning.','', '## Amendment 4','',f'`## Amendment 4: final-model re-runs (exploratory)` was the first Phase6 mutation, appended to `holdout/PREREGISTRATION_R2_HOLDOUT.md` at {amend["utc"]}, before preparation, fitting or inference. It contains Parts I and T and the entire approved prompt verbatim.','',f'SHA-256 of the preregistration bytes through Amendment 4 before its receipt: `{amend["amendment4_sha256"]}`. The preceding {amend["previous_bytes"]} bytes retain SHA-256 `{amend["previous_sha256"]}`. Receipt: [AMENDMENT4_RECEIPT.json](AMENDMENT4_RECEIPT.json).','', '## Boundaries and interpretation','']
 lines += ['- '+d for d in deviations]
 lines += ['', '## Training log','',table(logrows),'','All configuration parameters, epoch histories, checkpoint hashes and durations are in [TRAINING_RESULTS_PHASE6.json](TRAINING_RESULTS_PHASE6.json); the compact log is [TRAINING_LOG_PHASE6.csv](TRAINING_LOG_PHASE6.csv). Each new configuration trained three independent attention–linear prerequisites and three matched T-OPT teachers before its three TRACE seeds. The teacher-logit target is the equal mean of that configuration’s three teachers, and the route target is its matched-seed teacher. The r4.2 attention–linear reference reuses the new attention–linear prerequisite checkpoint, selected on r4.2 VALIDATION.','', '## Part I1: order and partial history','',table(i['order_history']),'','T0 is original, T1 reversed, T2 the single fixed seed2026 permutation, T3/T4/T5 retain the most recent 1/5/10 days with earlier timesteps filled by frozen original TRAIN medians, and T6 is the identical 20-day original reference. Frozen thresholds are reused. Clean predictions are taken from saved frozen predictions; a fresh-forward parity check precedes interventions.','',table(i['clean_frozen_prediction_parity']),'','Paired user-cluster percentile 95% intervals use 2000 draws, seed42. The same user multiplicities are paired across conditions and fixed model seeds; `mean_three` is the mean of the three per-seed metrics, not AP of averaged scores. Single-class draws are reported in the valid replicate count.','',table(i['order_history_CIs']),'', '## Part I2: identical information','',table(i['same_information']),'',table(i['same_information_CIs']),'', '## Part I3: multi-day cohort','',table(i['multi_day']),'','All models use their frozen predictions, with the identical allowed cohort G. Multi-day means at least two malicious calendar days within a completed 20-day window; all allowed benign validation windows are included as negatives. One answer-file incident per positive user is inherited from the frozen historical cohort definition.','', '## Part I4: TRACE attention','',table(i['attention_cases']),'',table(i['attention_CIs']),'','All individual interventions and matched-control means are in [I4_ATTENTION_EFFECTS.csv](I4_ATTENTION_EFFECTS.csv). Each selected case and k has 25 matched random controls for deletion and another 25 for retention. Only pseudonyms and row indices are public; raw CERT IDs stay in the private input metadata.','', '## Parts T1/T2: validation design-choice results','',table(t['validation']),'', '### T2 paired feature-set contrasts','',table(t['feature_CIs']),'', '## Part T3: r4.2 independent TEST','',table(t['r42_test']),'',table(t['r42_test_CIs']),'','The new r4.2 models, thresholds and their hashes were frozen in [T3_MODELS_FROZEN_BEFORE_TEST.json](T3_MODELS_FROZEN_BEFORE_TEST.json) before opening the r4.2 TEST metadata/activity. The original chronological partition boundaries and TRAIN-fitted scaler were preserved; one exclusive campaign sentinel prevents repeated TEST scoring. All twelve model/seed configurations were evaluated once if training succeeded. Cohort details: [T3_TEST_COHORT_RECEIPT.json](T3_TEST_COHORT_RECEIPT.json).','', '## Figures and source data','']
 for n in names:lines += [f'![{n}]({n}.png)','',f'[300 dpi PNG]({n}.png) · [data CSV]({n}_data.csv)','']
 lines += ['## Skips and deviations','',table(skips) if skips else 'No model training, inference or required comparison was skipped. The preparation compatibility fixes and cohort restrictions are disclosed above.','', '## Evidence and verification','', '[PHASE6_RESULTS.json](PHASE6_RESULTS.json) contains all result tables, full training histories, protocols, checkpoint hashes, cohort manifests and deviations. [FINAL_VERIFICATION.json](FINAL_VERIFICATION.json) records integrity checks. Existing model/checkpoint hashes are verified; the preregistration prefix and Amendment 4 receipt are checked. All public identifiers are pseudonyms. Figures have matching data CSVs and at least 300 dpi metadata.','', 'PHASE6_COMPLETE']
 text='\n'.join(lines)+'\n';assert not re.search(r'\b[A-Z]{3}[0-9]{4}\b',text);(OUT/'CHATGPT_PHASE6_REPORT.md').write_text(text,encoding='utf-8')
 status('PHASE6_COMPLETE',report=str(OUT/'CHATGPT_PHASE6_REPORT.md'))
